/// 📐️ `…From2PointsAndHeight`: the committed typology's declared construction (`construction.from2PointsAndHeight`,
/// `🧬️typology/🧬️schema/🔣️.json`) plans the object from the picks A, B and the height
/// ([`crate::editor::cad::engine::typology::plan_from_2_points_and_height`]). The object persists the plan's frame — origin,
/// yaw about +Z, extent along its local axes — so a wall follows its baseline, a surface plan keeps a flat extent (a face) and a
/// curve plan a one-axis extent (a line); the seed handle is the local shape `typology_local_shape` rebuilds from that extent.
fn commit_from_2_points_and_height(kernel: &mut Brep, params: &HashMap<String, DslValue>, label: &str, label_count: usize, next_id: impl Fn(&str) -> String) -> CommitOutcome {
    use crate::editor::cad::engine::typology::{load_typology, plan_from_2_points_and_height, ConstructionPlan, ConstructionPrimitive, CONSTRUCTION_DEGENERATE_INPUT};
    let Some(typology) = params.get("typology").and_then(|value| value.as_str()) else {
        return CommitOutcome::Refused(format!("{CONSTRUCTION_DEGENERATE_INPUT}: the commit names no typology"));
    };
    let Some(construction) = load_typology(typology).and_then(|spec| spec.construction.as_ref()) else {
        return CommitOutcome::Refused(format!("{CONSTRUCTION_DEGENERATE_INPUT}: {typology} declares no construction"));
    };
    let (Some(a), Some(b), Some(height)) = (params.get("pointA").and_then(parse_vec3), params.get("pointB").and_then(parse_vec3), params.get("height").and_then(|value| value.as_f64())) else {
        return CommitOutcome::Refused(format!("{CONSTRUCTION_DEGENERATE_INPUT}: the commit carries no pointA, pointB and height"));
    };
    let spec = &construction.from_2_points_and_height;
    let plan = match plan_from_2_points_and_height(spec, a, b, height) {
        Ok(plan) => plan,
        Err(refusal) => return CommitOutcome::Refused(format!("{CONSTRUCTION_DEGENERATE_INPUT}: {}", refusal.en)),
    };
    let yaw_of = |direction: [f64; 3]| direction[1].atan2(direction[0]);
    let difference = |p: [f64; 3], q: [f64; 3]| [q[0] - p[0], q[1] - p[1], q[2] - p[2]];
    let norm = |v: [f64; 3]| (v[0] * v[0] + v[1] * v[1] + v[2] * v[2]).sqrt();
    let (origin, yaw, extent) = match plan {
        ConstructionPlan::Prism { origin, x_axis, extents, .. } => (origin, yaw_of(x_axis), extents),
        ConstructionPlan::Cylinder { base, radius, height } => (base, 0.0, [2.0 * radius, 2.0 * radius, height]),
        ConstructionPlan::Quad { corners } => {
            let (u, v) = (difference(corners[0], corners[1]), difference(corners[0], corners[3]));
            if v[2].abs() > 0.0 { (corners[0], yaw_of(u), [norm(u), 0.0, norm(v)]) } else { (corners[0], yaw_of(u), [norm(u), norm(v), 0.0]) }
        }
        ConstructionPlan::Line { start, end } => {
            let d = difference(start, end);
            if d[2].abs() > 0.0 { (start, 0.0, [0.0, 0.0, norm(d)]) } else { (start, yaw_of(d), [norm(d), 0.0, 0.0]) }
        }
    };
    let Some(seed) = crate::standards::v1::subsets::any::schema::inferences::typology_local_shape(kernel, typology, Some(extent)) else {
        return CommitOutcome::Refused(format!("{CONSTRUCTION_DEGENERATE_INPUT}: the kernel builds no shape of extent {extent:?}"));
    };
    let slot = match spec.primitive {
        ConstructionPrimitive::Solid => "solid",
        ConstructionPrimitive::Surface => "surface",
        ConstructionPrimitive::Curve => "curve",
    };
    let (sine, cosine) = (yaw * 0.5).sin_cos();
    CommitOutcome::Objects(vec![CadObject {
        id: next_id("object"),
        label: format!("{label} {}", label_count + 1),
        typology: typology.to_string(),
        visible: true,
        locked: false,
        origin,
        orientation: Some([0.0, 0.0, sine, cosine]),
        scale: None,
        mesh_url: None,
        extent: Some(extent),
        solid_handle: Some(seed.0.clone()),
        primitives: vec![CadPrimitiveSlot { slot: slot.into(), primitive_id: seed.0, kind: slot.into() }],
    }])
}

