/// 📐️ LAW: a diagonal wall follows its baseline — the committed object's frame rebuilds, in the kernel, the prism the
/// construction vectors fix (`wall-diagonal`: 3-4-5 baseline, 0.3 m centred, 2.7 m high → 4.05 m³ centred over the baseline's
/// midpoint), never the picks' bounding box.
#[semio_framework_async_macros::async_test]
async fn building_wall_follows_a_diagonal_baseline() {
    let mut session = start_session("building.building.placeWall", CadPaneId::Building).expect("session");
    assert!(apply_event(&mut session, "start", None));
    assert!(apply_event(&mut session, "pointer.down", Some(&point_arg(1.0, 1.0, 0.0))));
    assert!(apply_event(&mut session, "pointer.down", Some(&point_arg(4.0, 5.0, 0.0))));
    let mut kernel = Brep::new();
    let object = commit_object(&mut kernel, &session, 0, |prefix| format!("{prefix}-1")).expect("wall");
    assert_eq!(object.extent, Some([5.0, 0.3, 2.7]));
    let [x, y, z, w] = object.orientation.expect("orientation");
    assert!(x.abs() < 1e-12 && y.abs() < 1e-12 && (2.0 * z.atan2(w) - 0.8f64.atan2(0.6)).abs() < 1e-12, "yaw follows A→B: {:?}", object.orientation);
    let world = crate::standards::v1::subsets::any::schema::inferences::pane_world_solids(&mut kernel, std::slice::from_ref(&object), None);
    assert_eq!(world.len(), 1);
    assert!((kernel.volume(&world[0]).expect("volume") - 4.05).abs() < 1e-9, "|AB| · 0.3 · 2.7");
    let center = kernel.center_of_mass(&world[0]).expect("centre of mass");
    for (axis, want) in [2.5, 3.0, 1.35].into_iter().enumerate() {
        assert!((center[axis] - want).abs() < 1e-6, "centre of mass {center:?} over the baseline midpoint");
    }
}

