/// 📐️ The Rust twin of the TS `planFrom2PointsAndHeight`: reads picks A, B and height h the way `spec` declares — the vectors
/// `🧫️fixtures/📐️construction-from-2-points/🔣️.json` fix every reading and every refusal.
pub fn plan_from_2_points_and_height(spec: &From2PointsAndHeightSpec, a: [f64; 3], b: [f64; 3], height: f64) -> Result<ConstructionPlan, ConstructionRefusal> {
    if !a.iter().chain(b.iter()).all(|value| value.is_finite()) {
        return Err(construction_refusal("The picked points are not finite.", "Die gewählten Punkte sind nicht endlich."));
    }
    if !(height.is_finite() && height > CONSTRUCTION_EPSILON) {
        return Err(construction_refusal("The height must be a positive length.", "Die Höhe muss eine positive Länge sein."));
    }
    let (dx, dy) = (b[0] - a[0], b[1] - a[1]);
    let length = dx.hypot(dy);
    let base_b = [b[0], b[1], a[2]];
    let lift = |p: [f64; 3], dz: f64| [p[0], p[1], p[2] + dz];
    let segment = || if length > CONSTRUCTION_EPSILON { Ok(()) } else { Err(construction_refusal("The two points coincide in plan: the baseline has no direction.", "Die beiden Punkte fallen im Grundriss zusammen: die Grundlinie hat keine Richtung.")) };
    let footprint = || if dx.abs() > CONSTRUCTION_EPSILON && dy.abs() > CONSTRUCTION_EPSILON { Ok(()) } else { Err(construction_refusal("The two corners span no footprint.", "Die beiden Ecken spannen keinen Grundriss auf.")) };
    match (spec.primitive, spec.profile) {
        (ConstructionPrimitive::Solid, ConstructionProfile::Segment) => {
            segment()?;
            let thickness = spec.thickness.filter(|value| value.is_finite() && *value > 0.0).ok_or_else(|| construction_refusal("The typology declares no wall thickness.", "Die Typologie gibt keine Wandstärke an."))?;
            let x_axis = [dx / length, dy / length, 0.0];
            let y_axis = [-x_axis[1], x_axis[0], 0.0];
            let alignment = spec.alignment.ok_or_else(|| construction_refusal("The typology declares no wall alignment.", "Die Typologie gibt keine Wandausrichtung an."))?;
            let shift = match alignment {
                ConstructionAlignment::Center => -thickness / 2.0,
                ConstructionAlignment::Left => 0.0,
                ConstructionAlignment::Right => -thickness,
            };
            Ok(ConstructionPlan::Prism { origin: [a[0] + shift * y_axis[0], a[1] + shift * y_axis[1], a[2]], x_axis, y_axis, extents: [length, thickness, height] })
        }
        (ConstructionPrimitive::Solid, ConstructionProfile::Rectangle) => {
            footprint()?;
            Ok(ConstructionPlan::Prism { origin: [a[0].min(b[0]), a[1].min(b[1]), a[2]], x_axis: [1.0, 0.0, 0.0], y_axis: [0.0, 1.0, 0.0], extents: [dx.abs(), dy.abs(), height] })
        }
        (ConstructionPrimitive::Solid, ConstructionProfile::Circle) => {
            segment()?;
            Ok(ConstructionPlan::Cylinder { base: a, radius: length, height })
        }
        (ConstructionPrimitive::Surface, ConstructionProfile::Segment) => {
            segment()?;
            Ok(ConstructionPlan::Quad { corners: [a, base_b, lift(base_b, height), lift(a, height)] })
        }
        (ConstructionPrimitive::Surface, ConstructionProfile::Rectangle) => {
            footprint()?;
            let (x0, x1, y0, y1, z) = (a[0].min(b[0]), a[0].max(b[0]), a[1].min(b[1]), a[1].max(b[1]), a[2] + height);
            Ok(ConstructionPlan::Quad { corners: [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]] })
        }
        (ConstructionPrimitive::Curve, ConstructionProfile::Segment) => {
            segment()?;
            Ok(ConstructionPlan::Line { start: lift(a, height), end: lift(base_b, height) })
        }
        (ConstructionPrimitive::Curve, ConstructionProfile::Point) => Ok(ConstructionPlan::Line { start: a, end: lift(a, height) }),
        (primitive, profile) => Err(construction_refusal(&format!("A {} cannot be built from a {} profile.", primitive_label(primitive), profile_label(profile)), &format!("Ein {} lässt sich nicht aus einem {}-Profil bilden.", primitive_label(primitive), profile_label(profile)))),
    }
}

fn primitive_label(primitive: ConstructionPrimitive) -> &'static str {
    match primitive {
        ConstructionPrimitive::Solid => "solid",
        ConstructionPrimitive::Surface => "surface",
        ConstructionPrimitive::Curve => "curve",
    }
}

fn profile_label(profile: ConstructionProfile) -> &'static str {
    match profile {
        ConstructionProfile::Segment => "segment",
        ConstructionProfile::Rectangle => "rectangle",
        ConstructionProfile::Circle => "circle",
        ConstructionProfile::Point => "point",
    }
}
