fn cylindrical_typologies_are_the_circle_constructions() {
    use crate::standards::v1::subsets::any::schema::inferences::typology_mesh_kind;
    for spec in list_model_definition_typologies() {
        let circle = spec.construction.as_ref().is_some_and(|construction| construction.from_2_points_and_height.profile == ConstructionProfile::Circle);
        assert_eq!(typology_mesh_kind(&spec.id) == "cylinder", circle || spec.id == "spatial.shape.solid.cylinder", "{}", spec.id);
    }
}
