/// 🧊️ A typology's primitive as a local kernel shape, sized from its extent (or the universal fallback extent) — the one
/// size rule [`typology_brep_mesh`] tessellates and [`pane_world_solids`] exports. The extent's spanned axes say which
/// primitive: three → the typology's solid (cylinder, sphere or box), two → the planar face over the rectangle they span
/// (`0, eᵢ, eᵢ + eⱼ, eⱼ`, right-handed about eᵢ × eⱼ), one → the line along it; a construction's surface and curve objects
/// persist exactly such flat extents.
pub(crate) fn typology_local_shape(kernel: &mut Brep, typology: &str, extent: Option<[f64; 3]>) -> Option<GeometryHandle> {
    let extent = extent.unwrap_or(CAD_DEFAULT_TYPOLOGY_EXTENT);
    let spanned: Vec<usize> = (0..3).filter(|&axis| extent[axis] > CAD_EXTENT_EPSILON).collect();
    let along = |axis: usize| {
        let mut point = [0.0; 3];
        point[axis] = extent[axis];
        point
    };
    match spanned.as_slice() {
        [axis] => kernel.polyline_wire(&[[0.0; 3], along(*axis)]).ok(),
        [i, j] => {
            let (u, v) = (along(*i), along(*j));
            kernel.planar_face_from_points(&[[0.0; 3], u, [u[0] + v[0], u[1] + v[1], u[2] + v[2]], v]).ok()
        }
        [_, _, _] => match typology_mesh_kind(typology) {
            "cylinder" => kernel.cylinder_prim(extent[0].max(extent[1]) * 0.5, extent[2]),
            "sphere" => kernel.sphere_prim(extent[0].max(extent[1]).max(extent[2]) * 0.5),
            _ => kernel.box_prim(extent[0], extent[1], extent[2]),
        }
        .ok(),
        _ => None,
    }
}

