/** 🚫️ The one refusal code of a construction whose picks span nothing. */
export const CONSTRUCTION_DEGENERATE_INPUT = "construction.degenerate-input";

/** 🚫️ A refused construction: its English and German reason. */
export type ConstructionRefusal = { readonly code: typeof CONSTRUCTION_DEGENERATE_INPUT; readonly en: string; readonly de: string };

/** 📏️ Below this many metres two picks coincide and a span is empty. */
const CONSTRUCTION_EPSILON = 1e-6;

/** 📐️ Reads picks `a`, `b` and `height` the way `construction` declares — the TS twin of the Rust `plan_from_2_points_and_height`;
 * the vectors `🧫️fixtures/📐️construction-from-2-points` fix every reading and every refusal. */
export function planFrom2PointsAndHeight(construction: ConstructionFrom2PointsAndHeight, a: Vec3, b: Vec3, height: number): { readonly plan: ConstructionPlan } | { readonly refusal: ConstructionRefusal } {
  const refuse = (en: string, de: string) => ({ refusal: { code: CONSTRUCTION_DEGENERATE_INPUT, en, de } as const });
  if (![...a, ...b].every(Number.isFinite)) return refuse("The picked points are not finite.", "Die gewählten Punkte sind nicht endlich.");
  if (!(Number.isFinite(height) && height > CONSTRUCTION_EPSILON)) return refuse("The height must be a positive length.", "Die Höhe muss eine positive Länge sein.");
  const dx = b[0] - a[0];
  const dy = b[1] - a[1];
  const length = Math.hypot(dx, dy);
  const baseB: Vec3 = [b[0], b[1], a[2]];
  const lift = (p: Vec3, dz: number): Vec3 => [p[0], p[1], p[2] + dz];
  const noSegment = !(length > CONSTRUCTION_EPSILON);
  const noFootprint = !(Math.abs(dx) > CONSTRUCTION_EPSILON && Math.abs(dy) > CONSTRUCTION_EPSILON);
  const segmentRefusal = () => refuse("The two points coincide in plan: the baseline has no direction.", "Die beiden Punkte fallen im Grundriss zusammen: die Grundlinie hat keine Richtung.");
  const footprintRefusal = () => refuse("The two corners span no footprint.", "Die beiden Ecken spannen keinen Grundriss auf.");
  if (construction.primitive === "solid" && construction.profile === "segment") {
    if (noSegment) return segmentRefusal();
    const xAxis: Vec3 = [dx / length, dy / length, 0];
    const yAxis: Vec3 = [-xAxis[1], xAxis[0], 0];
    const shift = construction.alignment === "center" ? -construction.thickness / 2 : construction.alignment === "left" ? 0 : -construction.thickness;
    return { plan: { kind: "prism", origin: [a[0] + shift * yAxis[0], a[1] + shift * yAxis[1], a[2]], xAxis, yAxis, extents: [length, construction.thickness, height] } };
  }
  if (construction.primitive === "solid" && construction.profile === "rectangle") {
    if (noFootprint) return footprintRefusal();
    return { plan: { kind: "prism", origin: [Math.min(a[0], b[0]), Math.min(a[1], b[1]), a[2]], xAxis: [1, 0, 0], yAxis: [0, 1, 0], extents: [Math.abs(dx), Math.abs(dy), height] } };
  }
  if (construction.primitive === "solid") {
    if (noSegment) return segmentRefusal();
    return { plan: { kind: "cylinder", base: a, radius: length, height } };
  }
  if (construction.primitive === "surface" && construction.profile === "segment") {
    if (noSegment) return segmentRefusal();
    return { plan: { kind: "quad", corners: [a, baseB, lift(baseB, height), lift(a, height)] } };
  }
  if (construction.primitive === "surface") {
    if (noFootprint) return footprintRefusal();
    const [x0, x1, y0, y1, z] = [Math.min(a[0], b[0]), Math.max(a[0], b[0]), Math.min(a[1], b[1]), Math.max(a[1], b[1]), a[2] + height];
    return { plan: { kind: "quad", corners: [[x0, y0, z], [x1, y0, z], [x1, y1, z], [x0, y1, z]] } };
  }
  if (construction.profile === "segment") {
    if (noSegment) return segmentRefusal();
    return { plan: { kind: "line", start: lift(a, height), end: lift(baseB, height) } };
  }
  return { plan: { kind: "line", start: a, end: lift(a, height) } };
}

/** 📐️ A construct action's params (`typology`, `pointA`, `pointB`, `height`) planned through that typology's construction — the
 * one entry both `SpatialKernel`s build `…From2PointsAndHeight` objects through. Throws `construction.degenerate-input` with the
 * English reason when the typology declares no construction, a pick or the height is missing, or the picks span nothing. */
export function constructionPlanFromParams(params: Record<string, unknown>): ConstructionPlan {
  const typologyId = typeof params.typology === "string" ? params.typology : "";
  const construction = loadTypology(typologyId)?.construction?.from2PointsAndHeight;
  if (!construction) throw new Error(`${CONSTRUCTION_DEGENERATE_INPUT}: ${typologyId || "the commit"} declares no construction`);
  const point = (value: unknown): Vec3 | null => (Array.isArray(value) && value.length === 3 && value.every((entry) => typeof entry === "number") ? (value as unknown as Vec3) : null);
  const a = point(params.pointA);
  const b = point(params.pointB);
  if (!a || !b || typeof params.height !== "number") throw new Error(`${CONSTRUCTION_DEGENERATE_INPUT}: the commit carries no pointA, pointB and height`);
  const planned = planFrom2PointsAndHeight(construction, a, b, params.height);
  if ("refusal" in planned) throw new Error(`${CONSTRUCTION_DEGENERATE_INPUT}: ${planned.refusal.en}`);
  return planned.plan;
}

