  return hexahedronModelDiff((i, j, k) => [i ? bx : ax, j ? by : ay, k ? z1 : z0], solid, { kind: "box", cornerA: [ax, ay, z0], cornerB: [bx, by, z0], height: z1 - z0 });
}

/** 📐️ A construction plan as `Model` records: a prism → the hexahedron over its frame (a shell-bounded solid `solid`), a cylinder
 * → the analytic cylinder solid `solid`, a quad → one planar face, a line → one wire (record ids prefixed by `solid`). */
export function constructionModelDiff(plan: ConstructionPlan, solid: SolidRef): ModelDiff {
  if (plan.kind === "prism") {
    const { origin, xAxis, yAxis, extents } = plan;
    return hexahedronModelDiff((i, j, k) => [0, 1, 2].map((axis) => origin[axis]! + i * extents[0] * xAxis[axis]! + j * extents[1] * yAxis[axis]! + (axis === 2 ? k * extents[2] : 0)) as unknown as Vec3, solid);
  }
  if (plan.kind === "cylinder") {
    return { solids: { added: [{ id: solid, shellIds: [], solid: { kind: "cylinder", base: plan.base, axis: [0, 0, 1], radius: plan.radius, height: plan.height } }] } };
  }
  const points = plan.kind === "quad" ? plan.corners : [plan.start, plan.end];
  const vertices = points.map((position, index) => ({ id: `${solid}-v${index}` as VertexRef, position }));
  const closed = plan.kind === "quad";
  const edges = vertices.slice(0, closed ? vertices.length : vertices.length - 1).map((vertex, index) => ({ id: `${solid}-e${index}` as EdgeRef, vertexIds: [vertex.id, vertices[(index + 1) % vertices.length]!.id], curve: { kind: "line" as const } }));
  const wire = { id: `${solid}-wire` as WireRef, edgeIds: edges.map((edge) => edge.id) };
  if (plan.kind === "line") return { vertices: { added: vertices }, edges: { added: edges }, wires: { added: [wire] } };
  const [c0, c1, , c3] = plan.corners;
  const u: Vec3 = [c1[0] - c0[0], c1[1] - c0[1], c1[2] - c0[2]];
  const v: Vec3 = [c3[0] - c0[0], c3[1] - c0[1], c3[2] - c0[2]];
  const normal = vec3Normalize([u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]]);
  return { vertices: { added: vertices }, edges: { added: edges }, wires: { added: [wire] }, faces: { added: [{ id: `${solid}-face` as FaceRef, wireIds: [wire.id], surface: { kind: "plane", origin: c0, normal } }] } };
}

